import json,base64,pathlib
root=pathlib.Path(__import__('sys').argv[1])
manifest=json.load(open(root/'manifest.json'))
source=pathlib.Path('/workspace/railway-game-ios/tools/station-kit/renderer.js').read_text().replace('export const directions','const directions').replace('export class NativeRenderer','class NativeRenderer')
source=source.replace('isometric:[1,-1,0.8]','isometric:[1,-1,0.25]')
source=source.replace('low[c]=Math.min(low[c],points[j][c]);high[c]=Math.max(high[c],points[j][c]);','if(color!==0xFFF6EEEC){low[c]=Math.min(low[c],points[j][c]);high[c]=Math.max(high[c],points[j][c]);}')
source=source.replace('data[k+9]=flags&1;','data[k+9]=color===0xFFF6EEEC?-1:(flags&1);')
source=source.replace('void main(){float sun=','void main(){if(g<0.0)discard;float sun=')
source=source.replace('precision highp float;in vec3 n,c;in float g;out vec4 outColor;','precision highp float;in vec3 n,c;in float g;uniform float night;out vec4 outColor;')
source=source.replace('outColor=vec4(c*(0.8+0.2*sun)+vec3(g*0.025),1.0);','outColor=vec4(c*(0.8+0.2*sun)*(1.0-0.40*night+1.10*g*night)+vec3(g*(0.025+0.20*night),g*(0.02+0.16*night),g*(0.01+0.10*night)),1.0);')
source=source.replace("['centre','right','up','direction','radius','aspect','depth']","['centre','right','up','direction','radius','aspect','depth','night']")
source=source.replace('zoom=1,vector}={}', 'zoom=1,vector,night=0,focus}={}')
source=source.replace('const projected=axis=>this.extent.reduce', 'const centre=focus?.centre||this.centre,extent=focus?.extent||this.extent;const projected=axis=>extent.reduce')
source=source.replace('Math.max(...this.extent)*3+1','Math.max(...extent)*3+1')
source=source.replace('centre:this.centre,right,up,direction','centre,right,up,direction')
source=source.replace('gl.drawArrays(gl.TRIANGLES,0,this.count);','gl.uniform1f(this.uniforms.night,night);gl.drawArrays(gl.TRIANGLES,0,this.count);')
data={m['id']:base64.b64encode((root/m['native']).read_bytes()).decode() for m in manifest['models']}
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><title>車站外觀第二批</title><style>body{font:16px system-ui;background:#eceef6;color:#262c57;margin:16px}select{font:inherit;margin:4px;padding:6px}canvas{max-width:100%;background:transparent}main{max-width:900px;margin:auto}#stage{background:#dfe7ef;border-radius:12px;text-align:center;padding:12px}</style><main><h1>車站外觀第二批</h1><p>獨立研究模型，近景／遠景、日／夜與七向。可離線開啟。</p><label>站體 <select id="model"></select></label><label>方向 <select id="direction"></select></label><label>光線 <select id="light"><option value="0">日</option><option value="1">夜</option></select></label><div id="stage"><canvas id="canvas"></canvas></div><p>OSM © OpenStreetMap contributors，ODbL 1.0；推估見 README。</p></main><script>'''+source+'\nconst models='+json.dumps(data)+';const modelSelect=document.getElementById("model"),directionSelect=document.getElementById("direction"),lightSelect=document.getElementById("light");for(const id of Object.keys(models))modelSelect.add(new Option(id,id));for(const d of Object.keys(directions))directionSelect.add(new Option(d,d));directionSelect.value="isometric";const renderer=new NativeRenderer(document.getElementById("canvas"));function load(id){const bytes=Uint8Array.from(atob(models[id]),c=>c.charCodeAt(0));renderer.load(bytes.buffer)}function redraw(){load(modelSelect.value);renderer.render(directionSelect.value,{width:800,height:600,night:Number(lightSelect.value),focus:{centre:[-84,137,5],extent:[28,32,11]}});return renderer.png()}window.renderModel=(id,d,night,vector,focus)=>{modelSelect.value=id;directionSelect.value=d;lightSelect.value=String(night);if(vector||focus){load(id);renderer.render(d,{width:800,height:600,night:Number(night),vector,focus});return renderer.png()}return redraw()};for(const e of [modelSelect,directionSelect,lightSelect])e.addEventListener("change",redraw);redraw();</script></html>'
(root/'viewer.html').write_text(html)
print(len(html))
